CREATE TABLE cap19_categories (category_id INTEGER PRIMARY KEY, category_name TEXT NOT NULL UNIQUE);
CREATE TABLE cap19_products (product_id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES cap19_categories(category_id), product_name TEXT NOT NULL, unit_price REAL NOT NULL CHECK (unit_price >= 0), stock_qty INTEGER NOT NULL CHECK (stock_qty >= 0));
INSERT INTO cap19_categories VALUES (1, 'Accessories'), (2, 'Stationery');
INSERT INTO cap19_products VALUES (1, 1, 'USB Cable', 250, 20), (2, 1, 'Phone Case', 400, 12), (3, 2, 'Notebook', 60, 50);
SELECT p.product_name, c.category_name FROM cap19_products AS p JOIN cap19_categories AS c ON c.category_id = p.category_id ORDER BY p.product_id;

